<?php
session_start();
if(!isset($_SESSION["adminsid"])){header("Location: ../index.php?msg=Please+log+in+as+Admin");exit();}
require_once __DIR__.'/../includes/db.php';$db=new db();$db->setconnection();$conn=$db->getConnection();$msg=null;
if($_SERVER["REQUEST_METHOD"]==="POST"&&isset($_POST['request_id'],$_POST['status'])){$request_id=(int)$_POST['request_id'];$status=$_POST['status'];if(!in_array($status,['Approved','Declined'],true)){$msg="Invalid request status.";}else{$stmt=$conn->prepare("UPDATE requests SET status=? WHERE request_id=?");$stmt->bind_param("si",$status,$request_id);$stmt->execute();$msg=$stmt->affected_rows>0?"Status updated successfully!":"No request was updated.";$stmt->close();}}
$result=$conn->query("SELECT request_id,student_id,isbn,book_name,status FROM requests ORDER BY CASE WHEN status NOT IN ('Approved','Declined') THEN 0 ELSE 1 END,request_id ASC");
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Book Requests | LMS</title><link rel="stylesheet" href="../assets/css/style.css"></head><body class="dashboard-page"><main class="wide-container"><header class="dashboard-header"><div><span class="eyebrow">Library Management System</span><h1>Book Requests</h1><p>Review and update student borrowing requests.</p></div><a class="logout-link" href="../logout.php">Logout</a></header><?php if($msg!==null):?><div class="alert alert-success"><?php echo htmlspecialchars($msg);?></div><?php endif;?><div class="page-actions"><a class="secondary-action" href="admin_service_dashboard.php">← Back to Dashboard</a></div><section class="request-grid"><?php if($result&&$result->num_rows>0):while($row=$result->fetch_assoc()):?><article class="request-card"><div class="request-card-top"><span class="request-id">Request #<?php echo (int)$row['request_id'];?></span><span class="status-badge"><?php echo htmlspecialchars($row['status']);?></span></div><dl class="request-details"><div><dt>Student ID</dt><dd><?php echo htmlspecialchars($row['student_id']);?></dd></div><div><dt>ISBN</dt><dd><?php echo htmlspecialchars($row['isbn']);?></dd></div><div><dt>Book</dt><dd><?php echo htmlspecialchars($row['book_name']);?></dd></div></dl><?php if($row['status']!=='Approved'&&$row['status']!=='Declined'):?><form method="POST" class="request-actions"><input type="hidden" name="request_id" value="<?php echo (int)$row['request_id'];?>"><button class="approve-btn" name="status" value="Approved">Approve</button><button class="decline-btn" name="status" value="Declined">Decline</button></form><?php endif;?></article><?php endwhile;else:?><div class="empty-state">No book requests found.</div><?php endif;?></section></main><?php $conn->close();?></body></html>